/**
 * Which language to offer somebody before they have said.
 *
 * The device's own language list is the right signal, and the only honest
 * one: it is what the person chose in their phone or browser, not a guess
 * about them. A timezone says roughly where a device is, and place is not
 * language — Istanbul speaks Turkish, Kurdish, Arabic and Persian, and a Turk
 * on holiday in Berlin is not German. So the zone is used only when the
 * language list says nothing we understand, and only to narrow a region down
 * to the language almost everyone there reads.
 *
 * When neither answers, nothing is chosen. For the question "what do you
 * already speak?", a wrong guess is worse than an empty one: it is somebody's
 * own language, they notice immediately, and a preselected wrong answer is
 * easy to walk past without noticing.
 */
import { LANGUAGES, type LanguageCode } from '@lexpad/core';

/**
 * Tags some devices report that mean a language we carry under another code.
 * Norwegian has two written forms and a macrolanguage tag; Filipino and
 * Tagalog are the same choice here; Chinese arrives in a dozen shapes.
 */
const ALIASES: Record<string, LanguageCode> = {
  nb: 'no',
  nn: 'no',
  fil: 'tl',
  cmn: 'zh',
  yue: 'zh',
  iw: 'he', // the old code for Hebrew, still sent by some Android builds
  in: 'id', // and the old code for Indonesian
  ji: 'he',
  mo: 'ro',
};

/**
 * The regions where one language is so dominant that the timezone is worth
 * reading. Anywhere genuinely multilingual is deliberately absent: a wrong
 * guess there is the exact mistake this is trying to avoid.
 */
const ZONE_LANGUAGE: Record<string, LanguageCode> = {
  'Asia/Tehran': 'fa',
  'Asia/Istanbul': 'tr',
  'Europe/Istanbul': 'tr',
  'Asia/Tokyo': 'ja',
  'Asia/Seoul': 'ko',
  'Asia/Bangkok': 'th',
  'Asia/Ho_Chi_Minh': 'vi',
  'Asia/Dhaka': 'bn',
  'Asia/Kathmandu': 'ne',
  'Asia/Colombo': 'si',
  'Asia/Yangon': 'my',
  'Asia/Phnom_Penh': 'km',
  'Asia/Vientiane': 'lo',
  'Asia/Tbilisi': 'ka',
  'Asia/Yerevan': 'hy',
  'Asia/Baku': 'az',
  'Asia/Tashkent': 'uz',
  'Asia/Almaty': 'kk',
  'Asia/Bishkek': 'ky',
  'Asia/Dushanbe': 'tg',
  'Asia/Kabul': 'ps',
  'Europe/Warsaw': 'pl',
  'Europe/Prague': 'cs',
  'Europe/Bratislava': 'sk',
  'Europe/Budapest': 'hu',
  'Europe/Bucharest': 'ro',
  'Europe/Sofia': 'bg',
  'Europe/Athens': 'el',
  'Europe/Lisbon': 'pt',
  'Europe/Madrid': 'es',
  'Europe/Rome': 'it',
  'Europe/Paris': 'fr',
  'Europe/Berlin': 'de',
  'Europe/Amsterdam': 'nl',
  'Europe/Stockholm': 'sv',
  'Europe/Oslo': 'no',
  'Europe/Copenhagen': 'da',
  'Europe/Helsinki': 'fi',
  'Europe/Reykjavik': 'is',
  'Europe/Tallinn': 'et',
  'Europe/Riga': 'lv',
  'Europe/Vilnius': 'lt',
  'Europe/Moscow': 'ru',
  'Europe/Kyiv': 'uk',
  'Europe/Kiev': 'uk',
  'Europe/Minsk': 'be',
  'Europe/Belgrade': 'sr',
  'Europe/Zagreb': 'hr',
  'Europe/Sarajevo': 'bs',
  'Europe/Ljubljana': 'sl',
  'Europe/Skopje': 'mk',
  'Europe/Tirane': 'sq',
  'Africa/Addis_Ababa': 'am',
  'Africa/Mogadishu': 'so',
  'Asia/Jakarta': 'id',
  'Asia/Kuala_Lumpur': 'ms',
  'Asia/Manila': 'tl',
};

/** Narrows any tag — "pt-BR", "nb-NO", "ZH" — to a language we carry. */
export function languageFromTag(tag: string): LanguageCode | undefined {
  const primary = tag.split('-')[0]?.toLowerCase() ?? '';
  if (primary === '') return undefined;
  const aliased = ALIASES[primary];
  if (aliased !== undefined) return aliased;
  return (LANGUAGES as readonly string[]).includes(primary) ? (primary as LanguageCode) : undefined;
}

/**
 * Every language the device names, best first and without repeats. The
 * pickers show these as suggestions; somebody who reads three languages
 * usually wants one of the three.
 */
export function deviceLanguages(): LanguageCode[] {
  if (typeof navigator === 'undefined') return [];
  const tags = navigator.languages.length > 0 ? navigator.languages : [navigator.language];
  const found: LanguageCode[] = [];
  for (const tag of tags) {
    const code = languageFromTag(tag);
    if (code !== undefined && !found.includes(code)) found.push(code);
  }
  return found;
}

/**
 * The language to start on, or nothing when the device gives no answer we
 * trust. Nothing is a real answer here, not a failure to produce one.
 */
export function likelyLanguage(): LanguageCode | undefined {
  const [best] = deviceLanguages();
  if (best !== undefined) return best;
  return zoneLanguage();
}

/** The language of the device's timezone, where a zone means only one. */
export function zoneLanguage(): LanguageCode | undefined {
  try {
    // Typed as always present, but an embedded web view with no Intl data
    // has been known to return nothing at all.
    const zone = Intl.DateTimeFormat().resolvedOptions().timeZone as string | undefined;
    return zone === undefined || zone === '' ? undefined : ZONE_LANGUAGE[zone];
  } catch {
    // Some embedded web views have no Intl data. Nothing to read is fine.
    return undefined;
  }
}
