import { useEffect, useMemo, useRef, useState } from 'react';
import { LANGUAGE_INFO, directionOf, type LanguageCode } from '@lexpad/core';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { deviceLanguages } from '@/lib/deviceLanguage.js';
import { PINNED_LANGUAGES, POPULAR_LANGUAGES } from '@/features/settings/data.js';
import styles from './LanguagePicker.module.css';

interface LanguagePickerProps {
  label: string;
  /** The languages on offer. */
  codes: readonly LanguageCode[];
  /** The current choice, or nothing when the question is still open. */
  value: LanguageCode | undefined;
  onPick: (code: LanguageCode) => void;
  /** A language to leave out, for example the one chosen on the other side. */
  exclude?: LanguageCode | undefined;
}

/** How many suggestions are worth showing before the list proper. */
const SUGGESTIONS = 5;

/**
 * Picks one language out of eighty without a wall of tiles.
 *
 * A search box first, because somebody who knows their language types four
 * letters and is done. Then a short suggested row — the languages the device
 * itself names, then the most chosen ones. Then everything else as one
 * alphabetical column with a sticky letter above each run, which is the
 * shape every contact list on earth uses and the only one that does not get
 * worse as the list grows.
 *
 * Whatever is already chosen is scrolled to when the picker opens, so
 * reopening it never starts by hiding the answer.
 */
export function LanguagePicker({
  label,
  codes,
  value,
  onPick,
  exclude,
}: LanguagePickerProps): React.JSX.Element {
  const [query, setQuery] = useState('');
  const list = useRef<HTMLDivElement>(null);
  const chosen = useRef<HTMLButtonElement>(null);

  const offered = useMemo(() => codes.filter((code) => code !== exclude), [codes, exclude]);
  const needle = query.trim().toLocaleLowerCase();

  const matches = useMemo(
    () =>
      needle === ''
        ? offered
        : offered.filter((code) => {
            const info = LANGUAGE_INFO[code];
            return (
              info.name.toLocaleLowerCase().includes(needle) ||
              info.native.toLocaleLowerCase().includes(needle) ||
              code === needle
            );
          }),
    [offered, needle],
  );

  const suggested = useMemo(() => {
    const picks: LanguageCode[] = [];
    const add = (code: LanguageCode): void => {
      if (offered.includes(code) && !picks.includes(code)) picks.push(code);
    };
    // English and Persian first and in that order, whatever the device
    // says. They are what this app is: English is what people come here to
    // learn, and Persian is who it was built for. A device that names one
    // of them does not push it down the row, because it is already there.
    PINNED_LANGUAGES.forEach(add);
    // Then what the device says: somebody who reads three languages usually
    // wants one of the three.
    deviceLanguages().forEach(add);
    for (const code of POPULAR_LANGUAGES) {
      if (picks.length >= SUGGESTIONS) break;
      add(code);
    }
    return picks;
  }, [offered]);

  const browsing = needle === '';
  const rest = useMemo(() => {
    const pool = browsing ? matches.filter((code) => !suggested.includes(code)) : [...matches];
    return pool.sort((a, b) => LANGUAGE_INFO[a].name.localeCompare(LANGUAGE_INFO[b].name));
  }, [browsing, matches, suggested]);

  // Reopening the picker must not start by hiding the answer. Only on the
  // first paint: doing it on every change would yank the list while
  // somebody is reading it.
  useEffect(() => {
    const target = chosen.current;
    const box = list.current;
    if (target === null || box === null) return;
    const above = target.offsetTop - box.offsetTop;
    if (above > box.clientHeight) box.scrollTop = above - box.clientHeight / 3;
  }, []);

  return (
    <div className={styles.picker}>
      <label className={styles.search}>
        <Icon name="search" size={16} weight={2} />
        <input
          type="search"
          className={styles.searchInput}
          value={query}
          placeholder={t('language.search')}
          aria-label={t('language.search')}
          autoCapitalize="off"
          autoCorrect="off"
          spellCheck={false}
          onChange={(event) => {
            setQuery(event.target.value);
          }}
        />
      </label>

      <div ref={list} role="radiogroup" aria-label={label} className={styles.list}>
        {browsing && suggested.length > 0 && (
          <>
            <p className={styles.heading}>{t('language.suggested')}</p>
            {suggested.map((code) => (
              <Row
                key={code}
                code={code}
                on={code === value}
                ref={code === value ? chosen : undefined}
                onPick={onPick}
              />
            ))}
          </>
        )}

        {rest.map((code, index) => {
          const letter = initial(code);
          const previous = rest[index - 1];
          const first = previous === undefined || initial(previous) !== letter;
          return (
            <div key={code} className={styles.run}>
              {browsing && first && <p className={cx(styles.heading, styles.letter)}>{letter}</p>}
              <Row
                code={code}
                on={code === value}
                ref={code === value ? chosen : undefined}
                onPick={onPick}
              />
            </div>
          );
        })}

        {matches.length === 0 && (
          <p className={styles.empty}>{t('language.none', { query: query.trim() })}</p>
        )}
      </div>
    </div>
  );
}

/** The letter a language files under. */
function initial(code: LanguageCode): string {
  return LANGUAGE_INFO[code].name.charAt(0).toLocaleUpperCase();
}

/** One language: its own name first, then what English calls it. */
function Row({
  code,
  on,
  onPick,
  ref,
}: {
  code: LanguageCode;
  on: boolean;
  onPick: (code: LanguageCode) => void;
  ref?: React.Ref<HTMLButtonElement> | undefined;
}): React.JSX.Element {
  const info = LANGUAGE_INFO[code];
  return (
    <button
      ref={ref}
      type="button"
      role="radio"
      aria-checked={on}
      className={cx(styles.row, on && styles.rowOn)}
      onClick={() => {
        onPick(code);
      }}
    >
      <span className={styles.native} lang={code} dir={directionOf(code)}>
        {info.native}
      </span>
      <span className={styles.name}>{info.name}</span>
      {on && (
        <span className={styles.check} aria-hidden="true">
          <Icon name="check" size={15} weight={2.5} />
        </span>
      )}
    </button>
  );
}
